// The character sheet PDF's fonts as base64, so they load from a <script> even when the page is opened from disk
// (file://), where fetch() can't read local files. sheet-pdf-ui.js loads this file the first time it makes a PDF.
// Chakra Petch (Bold, SemiBold) and Barlow Semi Condensed (Regular, SemiBold), from github.com/google/fonts, under
// the SIL Open Font License: see OFL-ChakraPetch.txt and OFL-BarlowSemiCondensed.txt. Made from the .ttf files
// that used to sit beside it; to change a font, encode the new .ttf the same way.
globalThis.NCD_SHEET_FONTS = {
  // ChakraPetch-Bold.ttf
  display: "",
  // ChakraPetch-SemiBold.ttf
  label: "",
  // BarlowSemiCondensed-Regular.ttf
  body: "",
  // BarlowSemiCondensed-SemiBold.ttf
  strong: "",
};
